Compared with the traditional method, we convert the optimization problem into an optimal control problem,
where the objective of each agent is to design the current control input minimizing the sum of the original objective function and updated size for the future time instant.
On the one hand, the problem studied in this paper includes the traditional results with multi-agents system, if we let $f_i(x_i(k))=f_i(x_i(N+1))=0$ while the system (\ref{1}) can be modified as $x_i(k+1)=Ax_i(k)+B_iu_i(k)$.
On the other hand, in the existing optimization algorithms to handle the problem (\ref{1}), there is a typical distributed first-order gradient descent algorithm \cite{ruder2016overview}:
\begin{equation}
{x_{i}(k+1)} = \sum\limits_{j=1}^{n}a_{ij}x_{j}(k) - \eta(k)\nabla f_{i}({x_i}(k)),\label{2}
\end{equation}
where  $\eta(k)$ is the step size.
                  
                                                       
                                                                                            
                
Noting that in convex optimization, it has been proven that using distributed algorithm (\ref{2}), {the global optimal solution for problem (\ref{1}) can be obtained}. However, distributed algorithm (\ref{2}) has limitations in terms of selecting the step size. The step size $\eta(k)$ in distributed algorithm (\ref{2}) should theoretically satisfy the following two conditions:
\begin{equation}
lim_{k \to \infty} \eta(k)=0,\label{78}
\end{equation}
\begin{equation}
\sum\limits_{k=1}^{\infty}\eta(k)=\infty.\label{77}
\end{equation}
In practical applications, the common practice for selecting the $\eta$ is to start with a small constant value. Alternatively, even if a time-varying step size $\eta(k)$ is chosen to satisfy the two conditions (\ref{78})-(\ref{77}), the results obtained from distributed algorithm (\ref{2}) are evidently influenced by the $\eta(k)$.
The distributed algorithm (\ref{2}) has limitations in terms of selecting the step size and
the results obtained from distributed algorithm (\ref{2}) are evidently influenced by the $\eta(k)$.

\label{Lemma1}
	If the Riccati equation (\ref{riccati}) admits solution such that ${\Gamma(k)}$ is invertible, then the control satisfies
	\begin{equation}
		{u(k)} = -\Gamma^{-1}(k)[B^TP(k+1)e(k)+\sum\limits_{l = k + 1}^{N + 1}M(l)\nabla f(l)], \label{uk}
	\end{equation}
    where {$M(l)=M(l-1)R(R+B^TP(i)B)^{-1} $ for $l> k+1$ and $M(l)=I$ for $l=k+1$}. Moreover, the costate equation is derived as
	\begin{equation}
		{\lambda(k-1)} = B^TP(k)e(k) + \sum\limits_{l = k}^{N + 1}M(l)\nabla f(l). \label{costate1}
	\end{equation}

Under the condition of Lemma 1 and based on the optimal control obtained from it, there exists an iteration algorithm
	\begin{equation}
		\begin{split}
			{x(k+1)} &= x(k)+d_k(x(k))\\
			{d_l(x(k))}&= -(\Gamma_P+h(k))^{-1}[g(k)-\Gamma_Pd_{l-1}(x(k))], \\
			d_0(x(k))&=-(\Gamma_P+h(k))^{-1}(g(k)+B^TPe(k)).\label{dk}
		\end{split}
	\end{equation}
	where $l=1,\dots,k$ means the required number of cycles, $g(k)=(\frac{1}{n}\boldsymbol {1}\boldsymbol {1^T})\nabla f(k)$ is average gradient, $h(k)=diag\{h_1(k),...,h_n(k)\}$, $h_i(k)=\frac{1}{n}\sum\limits_{i = 1}^{n}\nabla^2 f_i(x_i(k))$, $\Gamma_P$ represents the stable solution $P$ of (\ref{riccati}) used for $\Gamma(k)$.

{ The connection between algorithm \eqref{dk} and our previous work presented in \cite{Zhang2024} will be discussed}. On the one hand, if each agent does not have a local function to optimize, {i.e., $f_i(x_i(k))=f_i(x_i(N+1))=0$}, it is evident that the terms $g(k)$ and $h(k)$ in \eqref{dk} will not exist. {That is to  say,} \eqref{dk} transforms into the following form:
	\begin{equation}
	\begin{split}
		&{x(k+1)} = x(k)+d_k\\
		&d_k=-(\Gamma_P)^{-1}B^TPe(k).\label{condk}
	\end{split}
\end{equation}
In this case, $d_k$ corresponds to the form of the controller $u_k$ from Lemma 1  in {\cite{zhang2023distributed}} when the matrix $A$ is the identity matrix. On the other hand, if we only consider a  centralized optimization problem, or if the states during the iteration process of each agent are same, then $e(k)$ and the related $P$ will not exist.  Moreover,  \eqref{dk} degenerates into the following form:
	\begin{equation}
	\begin{split}
		{x(k+1)} &= x(k)+d_k(x(k))\\
		d_l(x(k))&= -(R+h(k))^{-1}[g(k)-Rd_{l-1}(x(k))], \\
		d_0(x(k))&=-(R+h(k))^{-1}g(k).\label{ocp}
	\end{split}
\end{equation}
where $l=1,\dots,k$ means the required number of cycles. In this case, \eqref{ocp} corresponds to Algorithm I in the previous work { \cite{Zhang2024}}, where $g(k)$ and $h(k)$ correspond to the (average) gradient and Hessian matrix, respectively.

{Now the connection between algorithm \eqref{ddk} and our previous work in {\cite{wang2024superlinear}} is discussed}. If we only consider a  centralized optimization problem, or if the states during the iteration process of each agent are the same, then $e(k)$ and the related $P$ will not exist.  {  In this case,} \eqref{ddk} { degrades} into the following form:
	\begin{equation}
	\begin{split}
		{x(k+1)} &= x(k)+\overline{d}_k(x(k))\\
    \overline{d}_l(x(k))&= -\eta g(k)+(I-\eta h(k))\overline{d}_{l-1}(x(k)), \\
    \overline{d}_0(x(k))&=-\eta g(k).\label{ocpl}
	\end{split}
\end{equation}
{  which is exactly Algorithm II in the previous work \cite{wang2024superlinear}.}

\label{thmmain0}
	                                          
Under the condition of Assumption \ref{assm2}, when $\{x(k)\}$ generated by DOCMC algorithm {  is convergent, then} there exists a scalar $r_1>0$ such that
	\begin{align}
		||x(k+1)-x^*||&\le r_1 \rho((\Gamma_P+h(k)))^{-1}\Gamma_P))^{k+1} \\
		&\times ||x(k)-x^*||, \label{conrate2}
	\end{align}
{  that is to say},  DOCMC algorithm is superlinearly convergent.

\label{thmmain}
Under the condition of Assumption \ref{assm2}, selecting $0<\eta < 1$ and $c=\|I-\eta h^*\|<1$,
when $\{x(k)\}$ generated by DOAOC algorithm converges, then there exists a scalar $r_2>0$ such that
	\begin{align}
		\|x(k+1)-x^*\|\le r_2 c^{k}\|x(k)-x^*\|. \label{conrate3}
	\end{align}
{  That is to say,}  DOAOC algorithm  is superlinearly convergent.
